from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class ProductIn(BaseModel):
    name: str = Field(min_length=1)
    price: float = Field(gt=0)

class ProductOut(BaseModel):
    id: int
    name: str
    price: float

@app.post("/products", response_model=ProductOut, status_code=201)
def create_product(data: ProductIn) -> ProductOut:
    return repository.create(data)

from typing import Annotated
from fastapi import HTTPException, Query

@app.get("/products/{product_id}")
def get_product(product_id: int):
    product = repository.find(product_id)
    if product is None:
        raise HTTPException(status_code=404, detail="Produto não encontrado")
    return product

@app.get("/products")
def list_products(page: int = 1, limit: Annotated[int, Query(le=100)] = 20):
    return repository.list(page=page, limit=limit)

from typing import Annotated
from fastapi import Depends
from sqlalchemy.orm import Session

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

Db = Annotated[Session, Depends(get_db)]

@app.get("/orders")
def list_orders(db: Db):
    return db.query(Order).all()

from typing import Annotated
from fastapi import Depends, HTTPException
from fastapi.security import OAuth2PasswordBearer

oauth2 = OAuth2PasswordBearer(tokenUrl="/auth/token")

def get_current_user(token: Annotated[str, Depends(oauth2)]) -> User:
    user = decode_jwt(token)  # None se inválido ou expirado
    if user is None:
        raise HTTPException(status_code=401, detail="Não autenticado")
    return user

CurrentUser = Annotated[User, Depends(get_current_user)]

@app.get("/me")
def me(user: CurrentUser):
    return user
